-- Blog rows correction: F-A-04, F-R5-01, F-R5-02 (audit 2026-09-29).
--
-- Rewrites meta_description, body_html, faq and external_links of the four seeded
-- posts in the LIVE blog_posts table. The seed in server.cjs only runs on an empty
-- table (and never overwrites), so editing code alone does not change production.
--
-- Run docs/runbooks/blog-rows-update.md first: export the current rows, THEN run
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f docs/runbooks/blog-rows-update.sql
-- (with the connection string from your secret store; never paste it into a file).
--
-- All or nothing: BEGIN ... COMMIT, and the DO block at the end raises (so psql stops
-- before COMMIT and the whole transaction is rolled back) unless all four rows exist
-- and none still carries a phrase the audit found false. published_at, title and
-- meta_title are not touched.
--
-- Generated from seedBlogPosts() in server.cjs; tests/blog-seed-claims.test.ts fails
-- if the two drift apart. Delete this file together with seedBlogPosts.

BEGIN;

UPDATE blog_posts SET
  meta_description = $blog_meta$A step-by-step SB 253 compliance roadmap for small and mid-sized businesses. Learn reporting thresholds, scope boundaries, and how to build a defensible GHG inventory.$blog_meta$,
  body_html = $blog_body$<h2>What SB 253 Means for Small and Mid-Sized Businesses</h2><p>California's Climate Corporate Data Accountability Act (SB 253) requires companies with more than $1 billion in annual revenue that do business in California to report their greenhouse gas (GHG) emissions. The direct reporting duty sits with those large companies. Its effects reach small and mid-sized businesses (SMBs) through their supply chains.</p><p>If your SMB supplies goods or services to a covered company, you may be asked for emissions data to support that company's own reporting. Building a defensible GHG inventory now puts you ahead of that request, before it becomes a contract requirement.</p><h2>Understanding the Reporting Timeline</h2><p>SB 253 phases in its requirements. The dates below reflect the statute and the California Air Resources Board (CARB) rulemaking as of September 29, 2026, and they are still moving. Check CARB's program page, linked below, for the current dates before you rely on them.</p><ul><li><strong>2026, Scope 1 and Scope 2:</strong> Covered companies report their Scope 1 and Scope 2 emissions. CARB's Initial Regulation sets November 10, 2026 as the first deadline. CARB has adopted that regulation, but as of September 29, 2026 it was still awaiting approval from California's Office of Administrative Law. Scope 3 is not required for 2026 reporting.</li><li><strong>2027 onward, Scope 3:</strong> Scope 3 reporting starts in 2027 on a schedule CARB has not yet set. CARB is developing the requirements for 2027 and later years in a second rulemaking.</li><li><strong>Assurance:</strong> The statute requires limited assurance on Scope 1 and Scope 2 reports beginning in 2026 and reasonable assurance beginning in 2030, and limited assurance on Scope 3 beginning in 2030. For the 2026 cycle, CARB has said it will accept reports whether or not assurance has been obtained.</li></ul><p>As an SMB, you are not directly covered by SB 253. Your larger customers may be, and they may ask for your emissions data through procurement surveys, supplier portals, and ESG questionnaires.</p><h2>Building a Defensible GHG Inventory</h2><p>A defensible GHG inventory is one that can withstand scrutiny from customers, assurance providers, and regulators. The GHG Protocol Corporate Standard provides the accounting framework:</p><ol><li><strong>Define organizational and operational boundaries.</strong> Decide which facilities, vehicles, and activities are included. Use either the equity share or control approach.</li><li><strong>Collect activity data.</strong> Gather utility bills, fuel receipts, purchase records, and freight invoices. The more granular, the better.</li><li><strong>Apply emission factors.</strong> Convert activity data (therms, kWh, gallons, dollars) into CO2e using published factors, such as those from the U.S. EPA (including eGRID for electricity).</li><li><strong>Document your methodology.</strong> Record which factors you used, where the data came from, and any assumptions. Reviewers and assurance providers will ask for this.</li></ol><h2>Scope 3: The Supply Chain Challenge</h2><p>Scope 3 emissions, those in your value chain, are often the largest part of a company's footprint, although the share varies widely by sector. For SMBs, the most relevant Scope 3 categories are usually:</p><ul><li><strong>Category 1: Purchased goods and services.</strong> The emissions embedded in everything you buy, from raw materials to office supplies.</li><li><strong>Category 4: Upstream transportation and distribution.</strong> Freight, shipping, and logistics.</li><li><strong>Category 11: Use of sold products.</strong> Relevant if your products consume energy during their lifetime.</li></ul><p>Start with a spend-based approach for Category 1: multiply purchase dollar amounts by industry-average emission factors. It is less precise than supplier-specific data, but it is a common starting point that you can refine over time.</p><h2>How Eco-Auditor Fits In</h2><p>Eco-Auditor is an emissions calculator for small and mid-sized businesses. It does not file anything with CARB and it does not provide assurance. Today it offers:</p><ul><li><strong>CSV import</strong> of activity data such as fuel, electricity, and spend records.</li><li><strong>Scope 1 and Scope 2 calculations</strong> on every plan, and <strong>Scope 3 calculations</strong> on the Growth and Pro plans. Factors come from the U.S. EPA (including eGRID) with IPCC AR5 global-warming potentials. Some factors, mostly for Scope 3, are Eco-Auditor internal estimates or provisional values, and the Methodology page explains which.</li><li><strong>A PDF emissions summary and a JSON data export</strong> that you can share with a customer who asks for your numbers.</li></ul><p>Not available yet (on the roadmap): supplier data requests, an audit trail of changes, framework-specific report templates, and accounting-software integrations.</p><h2>Key Takeaways</h2><ul><li>SB 253 applies directly to companies with more than $1 billion in revenue that do business in California, not to most SMBs.</li><li>Supply chain requests are the more likely way an SMB will feel SB 253. Start with Scope 1 and Scope 2, which are the easiest to measure and the first thing customers ask about.</li><li>Use spend-based methods for Scope 3 until you can collect supplier-specific data.</li><li>Document everything: a clear methodology matters more than false precision.</li></ul>$blog_body$,
  faq = $blog_faq$[{"question":"Does SB 253 apply to small businesses?","answer":"SB 253 directly applies to companies with more than $1 billion in annual revenue that do business in California. Smaller businesses are not directly covered, but customers that are covered may ask them for emissions data to support Scope 3 reporting."},{"question":"What is the deadline for SB 253 reporting?","answer":"CARB's Initial Regulation sets November 10, 2026 as the first deadline, for Scope 1 and Scope 2 emissions. As of September 29, 2026 that regulation was still awaiting approval from California's Office of Administrative Law. Scope 3 reporting is not required for 2026 and starts in 2027 on a schedule CARB has not yet set. Check CARB's program page for current dates."},{"question":"How do I calculate Scope 3 emissions as an SMB?","answer":"Start with a spend-based approach: multiply purchase dollar amounts by industry-average emission factors. This gives you an estimate without requiring supplier-specific data, and you can refine it over time."},{"question":"What emission factors should I use?","answer":"Use recognized published factors, for example U.S. EPA factors for US fuel and activity data and eGRID for electricity. Eco-Auditor uses EPA and eGRID factors with IPCC AR5 global-warming potentials; some factors, mostly for Scope 3, are internal estimates or provisional values, which its Methodology page explains."}]$blog_faq$::jsonb,
  external_links = $blog_links$[{"href":"https://ghgprotocol.org/corporate-standard","anchor":"GHG Protocol Corporate Standard"},{"href":"https://ww2.arb.ca.gov/our-work/programs/california-corporate-greenhouse-gas-reporting-and-climate-related-financial-risk","anchor":"CARB SB 253 program page"}]$blog_links$::jsonb
WHERE slug = 'sb-253-compliance-guide-smb'
RETURNING slug;

UPDATE blog_posts SET
  meta_description = $blog_meta$A practical guide to GHG Protocol Scope 3 emissions for small and mid-sized businesses. Learn which categories matter, how to measure them, and how to build a defensible inventory.$blog_meta$,
  body_html = $blog_body$<h2>Why Scope 3 Matters for SMBs</h2><p>Scope 3 emissions, the indirect emissions in your value chain, are often the largest part of a company's total carbon footprint, although the share varies widely by sector. For small and mid-sized businesses, Scope 3 can feel overwhelming because it covers everything from purchased goods to employee commuting. But ignoring it is getting harder.</p><p>Your larger customers may need your emissions data for their own Scope 3 disclosures. California's SB 253, for example, starts requiring Scope 3 reporting from large companies in 2027, on a schedule CARB has not yet set. Investors also increasingly factor carbon exposure into risk assessments. The good news: you do not need to measure all 15 Scope 3 categories to be defensible. You need to measure the ones that matter.</p><h2>The 15 Scope 3 Categories, Ranked for SMBs</h2><p>The GHG Protocol defines 15 Scope 3 categories. For most SMBs, only a handful are material:</p><h3>High priority (measure first)</h3><ul><li><strong>Category 1, Purchased goods and services:</strong> The emissions embedded in everything you buy. Usually the largest Scope 3 category for product-based businesses.</li><li><strong>Category 4, Upstream transportation and distribution:</strong> Freight, shipping, and logistics emissions from moving your inputs.</li><li><strong>Category 11, Use of sold products:</strong> If your products consume energy during use, this can dwarf everything else.</li></ul><h3>Medium priority (estimate when feasible)</h3><ul><li><strong>Category 5, Waste generated in operations:</strong> Use waste contractor data or estimate by waste type and volume.</li><li><strong>Category 6, Business travel:</strong> Flight and hotel data from expense systems.</li><li><strong>Category 7, Employee commuting:</strong> Survey-based or estimated by office size and region.</li></ul><h3>Low priority (screen and skip if immaterial)</h3><ul><li><strong>Categories 2, 3, 8, 9, 10, 12, 13, 14, 15:</strong> For most SMBs, these are either zero, negligible, or not applicable. Document that you screened them and explain why they are immaterial.</li></ul><h2>How to Measure Scope 3 Without a Sustainability Team</h2><p>You do not need a dedicated sustainability team to build a credible Scope 3 inventory. Here is the practical path:</p><ol><li><strong>Start with spend data.</strong> Export your accounts payable ledger and categorize purchases by industry sector. Multiply each category by a spend-based emission factor, such as the U.S. EPA's supply chain emission factors.</li><li><strong>Pull freight records.</strong> Your shipping invoices contain mode, distance, and weight. Apply the EPA SmartWay factors to estimate Category 4.</li><li><strong>Estimate product use.</strong> If you sell physical products that consume energy, estimate lifetime energy consumption and multiply by the grid emission factor.</li><li><strong>Document what you skipped and why.</strong> A screening explanation for the categories you did not measure is itself part of a defensible inventory.</li></ol><h2>Building a Defensible Methodology</h2><p>Defensibility means your numbers can survive external review. Three principles:</p><ul><li><strong>Traceability:</strong> Every number should link back to a source document.</li><li><strong>Consistency:</strong> Use the same emission factors and boundary definitions year over year.</li><li><strong>Transparency:</strong> Document your assumptions, exclusions, and estimation methods.</li></ul><h2>What Eco-Auditor Does for Scope 3 Today</h2><p>Scope 3 workflows are included on the Growth and Pro plans. The Starter plan covers Scope 1 and Scope 2 only. Today they offer:</p><ul><li><strong>Spend-based estimates:</strong> import purchase spend by category through a CSV file and get CO2e estimates for purchased goods and services.</li><li><strong>Activity-based estimates for some other categories,</strong> such as transportation, business travel, employee commuting, and waste.</li><li><strong>Clear labels on estimates:</strong> some Scope 3 factors are Eco-Auditor internal estimates rather than published datasets, and the Methodology page explains which.</li></ul><p>Not available yet (on the roadmap): supplier data requests, Scope 3 screening templates, framework-specific export formats, and accounting-software integrations.</p><h2>Key Takeaways</h2><ul><li>You do not need to measure all 15 Scope 3 categories. Focus on the 3-5 that are material to your business.</li><li>Spend-based methods are a common starting point for Category 1. Refine with supplier-specific data over time.</li><li>Documentation and screening explanations are part of a defensible inventory, not optional extras.</li><li>Start now. Your larger customers may already be asking for this data.</li></ul>$blog_body$,
  faq = $blog_faq$[{"question":"Which Scope 3 categories should an SMB measure first?","answer":"Start with Category 1 (purchased goods and services), Category 4 (upstream transportation), and Category 11 (use of sold products). These typically represent the largest share of Scope 3 emissions for SMBs."},{"question":"Is spend-based Scope 3 reporting defensible?","answer":"Yes, as an estimate. The GHG Protocol's Scope 3 guidance describes spend-based methods as an accepted way to estimate Category 1. They are less precise than supplier-specific data, so document your data sources, emission factors, and assumptions, and refine them over time."},{"question":"How do I screen Scope 3 categories I decide not to measure?","answer":"Document which categories you assessed, why they are immaterial, and keep this screening explanation as part of your inventory. This is standard GHG Protocol practice."},{"question":"Do I need third-party assurance for Scope 3?","answer":"Under SB 253, limited assurance on Scope 3 reporting begins in 2030 for covered companies, meaning those with more than $1 billion in revenue that do business in California. Smaller businesses are not directly subject to it, but clear documentation makes any customer's review easier."}]$blog_faq$::jsonb,
  external_links = $blog_links$[{"href":"https://ghgprotocol.org/corporate-value-chain-scope-3-standard","anchor":"GHG Protocol Scope 3 Standard"},{"href":"https://www.epa.gov/climateleadership/scope-3-inventory-guidance","anchor":"EPA Scope 3 guidance"}]$blog_links$::jsonb
WHERE slug = 'ghg-protocol-scope-3-guide-smb'
RETURNING slug;

UPDATE blog_posts SET
  meta_description = $blog_meta$A buyer's guide to carbon accounting software for small and mid-sized businesses. Compare features, pricing models, and must-have capabilities for 2026 compliance.$blog_meta$,
  body_html = $blog_body$<h2>Why SMBs Need Carbon Accounting Software Now</h2><p>Carbon accounting used to be a spreadsheet exercise managed by an external consultant once a year. In 2026, that approach is harder to justify. Larger customers covered by California's SB 253, and importers subject to the EU's CBAM, may ask their suppliers for emissions data, and they expect numbers that are documented and repeatable.</p><p>For SMBs, the challenge is finding software that fits your budget and team size without sacrificing the rigor that customers expect. Here is what to look for.</p><h2>Must-Have Features for SMB Carbon Accounting</h2><h3>1. Published emission factor libraries</h3><p>Your software should ship with emission factors from recognized sources such as the U.S. EPA and eGRID, so you do not have to research and enter them manually. Factors should be versioned and sourced, with the year shown for every number, and reviewed on a regular schedule.</p><h3>2. Scope 1, 2, and 3 support</h3><p>Many tools handle Scope 1 and 2 well but treat Scope 3 as an afterthought. For SMBs in the supply chains of large companies, Scope 3 is where the scrutiny is. Look for spend-based Category 1 calculation and clear labeling of which factors are estimates.</p><h3>3. Audit-ready documentation</h3><p>Every calculation should be traceable to its source data and emission factor. Look for audit trails that record who entered data, when it was modified, and which factors were applied.</p><h3>4. Customer-ready reporting</h3><p>Can the tool export what your customers ask for? Some ask for a simple PDF or spreadsheet, others for CDP responses or custom supplier questionnaires. Check which formats the tool actually supports before you buy.</p><h3>5. Supply chain survey tools</h3><p>The best way to improve Scope 3 data quality is to collect primary data from your suppliers. Some tools let you send suppliers a survey link and calculate their contributions. Check whether the feature is available today or only planned.</p><h2>Pricing Models: What Makes Sense for SMBs</h2><ul><li><strong>Per-facility pricing:</strong> Charged based on the number of facilities. Gets expensive for distributed operations.</li><li><strong>Per-user pricing:</strong> Charged per seat. Best for teams where only a few people need access.</li><li><strong>Tiered plans:</strong> Fixed monthly or annual price with feature gates. Best for SMBs: predictable cost, no surprises.</li></ul><p>Eco-Auditor uses tiered plans, billed monthly: Starter at $149/month (Scope 1 and 2 only, 1 facility, 10 CSV imports a month), Growth at $399/month (adds Scope 3, up to 5 facilities, unlimited CSV imports), and Pro at $999/month (unlimited facilities). Annual billing is also available. Compare plans on their limits as well as their price.</p><h2>Red Flags to Watch For</h2><ul><li><strong>"AI-generated" emission estimates with no methodology:</strong> If a tool gives you a carbon number without showing the underlying factors, it is not defensible.</li><li><strong>No Scope 3 support:</strong> Tools that only cover Scope 1 and 2 leave you unprepared for supply chain reporting requests.</li><li><strong>Unversioned or undated factors:</strong> If a tool does not show which factor set and year it used, you cannot reproduce or defend the number.</li><li><strong>No data export:</strong> If you cannot export your raw data, you are locked in.</li></ul><h2>The Spreadsheet Question</h2><p>Many SMBs start with Excel. That is fine for a first-pass estimate, but spreadsheets break down fast: no version control on emission factors, no audit trail, no validation, no factor updates. If you are spending more than two hours a month maintaining a carbon spreadsheet, it is worth evaluating dedicated software.</p><h2>How Eco-Auditor Compares</h2><p>Use the checklist above on us too. Here is where Eco-Auditor stands today:</p><ul><li><strong>Emission factors:</strong> U.S. EPA factors (including eGRID) with IPCC AR5 global-warming potentials. Some factors, mostly for Scope 3, are internal estimates or provisional values, and the Methodology page explains which.</li><li><strong>Scopes:</strong> Scope 1 and 2 on every plan, Scope 3 on Growth and Pro.</li><li><strong>Outputs:</strong> A PDF emissions summary and a JSON data export.</li><li><strong>Pricing:</strong> Starter at $149/month, Growth at $399/month, Pro at $999/month, with plans capped at 1 facility, 5 facilities, and unlimited facilities.</li><li><strong>Not available yet (on the roadmap):</strong> an audit trail, supplier surveys, framework-specific exports such as CDP or GRI, and accounting-software integrations.</li></ul><h2>Key Takeaways</h2><ul><li>Carbon accounting software is worth evaluating for SMBs in supply chains where customers ask for emissions data.</li><li>Look for published emission factors, Scope 3 support, an audit trail, and the reporting formats your customers actually ask for.</li><li>Avoid tools with opaque estimates, no Scope 3, or no data export.</li><li>Compare plans on their limits (facilities, scopes, imports) as well as their monthly price.</li></ul>$blog_body$,
  faq = $blog_faq$[{"question":"How much does carbon accounting software cost for an SMB?","answer":"Prices vary widely between vendors and depend on how many facilities and scopes you need, so compare limits as well as price. Eco-Auditor plans are Starter at $149/month, Growth at $399/month, and Pro at $999/month, billed monthly, with plans capped at 1 facility, 5 facilities, and unlimited facilities."},{"question":"Can I use Excel for carbon accounting?","answer":"Excel works for a first-pass estimate but breaks down due to lack of version control, audit trails, emission factor updates, and validation. Dedicated software saves time and reduces errors."},{"question":"What emission factors should carbon accounting software include?","answer":"Look for factors from recognized sources such as the U.S. EPA and eGRID. They should be versioned and sourced, with the year shown for every number."},{"question":"Do SMBs need Scope 3 reporting software?","answer":"Often, yes. Customers in regulated supply chains increasingly ask their suppliers for Scope 3 data. Look for software with spend-based Category 1 calculation and clear labeling of which factors are estimates."}]$blog_faq$::jsonb,
  external_links = $blog_links$[{"href":"https://ghgprotocol.org/","anchor":"GHG Protocol"},{"href":"https://www.epa.gov/climateleadership","anchor":"EPA Climate Leadership"}]$blog_links$::jsonb
WHERE slug = 'carbon-accounting-software-smb-guide'
RETURNING slug;

UPDATE blog_posts SET
  meta_description = $blog_meta$How the EU Carbon Border Adjustment Mechanism affects SMBs in US supply chains. Learn CBAM reporting requirements, embedded emissions, and how to prepare.$blog_meta$,
  body_html = $blog_body$<h2>What Is CBAM and Why Should SMBs Care?</h2><p>The EU Carbon Border Adjustment Mechanism (CBAM) puts a carbon price on certain goods imported into the European Union. It covers six sectors: cement, iron and steel, aluminium, fertilisers, hydrogen, and electricity. EU importers of those goods must report the emissions embedded in them and, from 2027, buy CBAM certificates to cover those emissions.</p><p>CBAM obligations fall on the importer. Importers must be authorised CBAM declarants, although importers bringing in less than 50 tonnes of CBAM goods a year (other than hydrogen and electricity) are exempt. If your SMB is a non-EU producer, you are not directly subject to CBAM. If you supply CBAM goods to EU customers, though, they may ask you for emissions data so that they can declare actual values instead of default values.</p><h2>CBAM Timeline: What Is Happening and When</h2><ul><li><strong>October 2023 to December 2025 (transitional period):</strong> Importers filed periodic reports of embedded emissions, with no financial obligation.</li><li><strong>From 1 January 2026 (definitive period):</strong> Importers must be authorised CBAM declarants, and the financial obligation applies to goods imported from this date.</li><li><strong>From 1 February 2027:</strong> CBAM certificate sales begin. The first annual CBAM declaration, together with the surrender of certificates for 2026 imports, is due by 30 September 2027.</li><li><strong>2026 to 2034:</strong> Free EU ETS allowances are phased out, so the CBAM adjustment applies to a growing share of embedded emissions.</li></ul><p>For SMB suppliers, the practical impact is that EU customers will want data they can rely on. The Commission's default values include a mark-up, so using verified actual data is usually more advantageous for them than falling back on defaults.</p><h2>Understanding Embedded Emissions</h2><p>CBAM focuses on embedded emissions, the greenhouse gases released while producing a good. What counts depends on the sector:</p><ul><li><strong>Direct emissions</strong> from the production process, including the production of heating and cooling, count for every CBAM good.</li><li><strong>Indirect emissions</strong> from the electricity consumed in production count only for cement and fertilisers (and agglomerated iron ore). For iron and steel, aluminium, and hydrogen, only direct emissions count.</li><li><strong>Precursors:</strong> For complex goods, the embedded emissions of relevant precursor materials, for example cement clinker in cement, are included.</li></ul><p>CBAM's boundary is specific to an installation and a product, so it is narrower than a full GHG inventory. It does not cover company-wide items such as employee commuting or business travel. CBAM also has its own calculation rules: for example, emission factors from life-cycle-assessment databases are not accepted for calculating embedded emissions.</p><h2>How to Calculate Embedded Emissions for CBAM</h2><ol><li><strong>Identify CBAM goods.</strong> Determine which of your products fall under the CBAM sectors. Customs (CN) codes and product descriptions determine coverage.</li><li><strong>Map your installation.</strong> Document which processes, equipment, and emission sources belong to the production of each CBAM good.</li><li><strong>Attribute emissions to production processes.</strong> If an installation runs several production processes, the EU sets rules for attributing shared inputs and emissions to each one (Annex III to Implementing Regulation (EU) 2025/2547). Follow those rules rather than choosing your own allocation method.</li><li><strong>Calculate the specific embedded emissions.</strong> Express the emissions per tonne of product using the methodology in the EU implementing rules, and keep the data ready for review by an accredited verifier.</li></ol><h2>What Your EU Customers Will Ask For</h2><p>EU importers submit an annual CBAM declaration. To complete it with actual values, they typically need from you:</p><ul><li>The total quantity of goods supplied (in tonnes)</li><li>The specific embedded emissions per tonne</li><li>The production installation's name, address, and country</li><li>The electricity emission factor used in production, where it is relevant to the goods (cement and fertilisers)</li><li>A description of the production process and system boundary</li></ul><p>If you cannot provide this data, your EU customer has to use the Commission's default values, which include a mark-up and are usually less favourable than verified actual data.</p><h2>How to Prepare as an SMB</h2><ol><li><strong>Audit your product portfolio.</strong> Identify any products in CBAM sectors and check their customs codes.</li><li><strong>Map your installation boundary.</strong> Document which processes and equipment produce CBAM goods.</li><li><strong>Start tracking production-specific energy use.</strong> Record electricity and fuel use for the lines that make CBAM goods.</li><li><strong>Ask your EU customers what they need.</strong> They must follow the EU rules when they declare, so ask which format and method they require.</li><li><strong>Prepare a standard data sheet.</strong> Keep one document you can send to any EU customer.</li></ol><h2>What Eco-Auditor Does and Does Not Do for CBAM</h2><p>Eco-Auditor is not a CBAM tool. It does not calculate CBAM embedded emissions, attribute emissions to products, or produce CBAM declarations or reports, and its emission factors are U.S. EPA based, with no EU grid factors. For CBAM data, use your customer's template or a CBAM-specific tool.</p><p>What it can do is help you keep a company-level GHG inventory from fuel, electricity, and spend records: CSV import, Scope 1 and Scope 2 calculations on every plan, and Scope 3 on the Growth and Pro plans, plus a PDF emissions summary.</p><h2>Key Takeaways</h2><ul><li>CBAM obligations sit with EU importers. Non-EU suppliers are not directly subject to CBAM, but their EU customers may ask them for installation-level emissions data.</li><li>CBAM's boundary is set by its own rules: direct emissions for every good, electricity only for cement and fertilisers, and including relevant precursors.</li><li>Without verified actual data, your customers must use default values that include a mark-up.</li><li>Start early: mapping an installation and collecting production-specific data takes time.</li></ul>$blog_body$,
  faq = $blog_faq$[{"question":"Does CBAM apply to small businesses?","answer":"CBAM obligations fall on EU importers of covered goods, who must be authorised CBAM declarants. Importers bringing in less than 50 tonnes a year of covered goods (other than hydrogen and electricity) are exempt. A small non-EU supplier is not directly subject to CBAM, but its EU customers may ask it for emissions data for the goods it supplies."},{"question":"What is the difference between CBAM embedded emissions and Scope 3 emissions?","answer":"CBAM embedded emissions are the emissions from producing a specific good: direct emissions for every CBAM good, plus indirect emissions from electricity for cement and fertilisers, including the embedded emissions of relevant precursor materials. Scope 3 covers value chain emissions for a whole company. CBAM's boundary is specific to an installation and a product."},{"question":"When does CBAM start charging for emissions?","answer":"The transitional period (reporting only) ran from October 2023 to December 2025. The definitive period began on 1 January 2026, so importers' financial obligation applies to goods imported from that date. CBAM certificates go on sale from 1 February 2027, and the first annual declaration and certificate surrender is due by 30 September 2027."},{"question":"How are emissions attributed to products?","answer":"If an installation has several production processes, CBAM sets rules for attributing shared inputs and emissions to each process and product (Annex III to Implementing Regulation (EU) 2025/2547). Follow those rules and your customer's template rather than choosing your own allocation method, and document how you applied them."}]$blog_faq$::jsonb,
  external_links = $blog_links$[{"href":"https://taxation-customs.ec.europa.eu/carbon-border-adjustment-mechanism_en","anchor":"EU CBAM official page"},{"href":"https://ghgprotocol.org/corporate-standard","anchor":"GHG Protocol Corporate Standard"}]$blog_links$::jsonb
WHERE slug = 'cbam-supply-chain-guide-smb'
RETURNING slug;

DO $check$
DECLARE
  found_rows integer;
  dirty_rows integer;
BEGIN
  SELECT count(*) INTO found_rows FROM blog_posts WHERE slug IN ('sb-253-compliance-guide-smb', 'ghg-protocol-scope-3-guide-smb', 'carbon-accounting-software-smb-guide', 'cbam-supply-chain-guide-smb');
  IF found_rows <> 4 THEN
    RAISE EXCEPTION 'expected the 4 seeded posts, found % - nothing was changed', found_rows;
  END IF;

  SELECT count(*) INTO dirty_rows FROM blog_posts
  WHERE slug IN ('sb-253-compliance-guide-smb', 'ghg-protocol-scope-3-guide-smb', 'carbon-accounting-software-smb-guide', 'cbam-supply-chain-guide-smb')
    AND (title || ' ' || meta_title || ' ' || meta_description || ' ' || body_html || ' ' || faq::text || ' ' || external_links::text)
        ~* '\$49|DEFRA|quarterly|2028|\$2 ?billion|\$2B|you are in scope|CBAM data pack|Supply chain surveys|CDP, GRI, TCFD|plus the emissions from electricity|must purchase CBAM certificates|climate-corporate-data-accountability';
  IF dirty_rows <> 0 THEN
    RAISE EXCEPTION '% row(s) still contain a phrase the audit found false - nothing was changed', dirty_rows;
  END IF;
END
$check$;

COMMIT;
